export function SurveyPrompt({
  question = "{{question}}",
  placeholder = "{{placeholder}}",
  accent = "{{accent}}",
  position = "{{position}}",
  dismissLabel = "{{dismissLabel}}",
}) {
  const pos = {
    corner: { width: 230, right: 16, bottom: 16 },
    banner: { left: 0, right: 0, top: 0, borderRadius: 0, display: "flex", alignItems: "center", gap: 14 },
    center: { width: 260, left: "50%", top: "50%", transform: "translate(-50%,-50%)" },
  }[position] ?? {};
  const isBanner = position === "banner";
  return (
    <div style={{ position: "relative", fontFamily: "system-ui, sans-serif", color: "#241430", width: 400, height: 220, background: "#FAF7F2", borderRadius: 14, border: "1px solid #24143018", overflow: "hidden" }}>
      <div style={{ position: "absolute", background: "#fff", borderRadius: 12, boxShadow: "0 10px 26px rgba(36,20,48,.2)", padding: isBanner ? "12px 18px" : "16px 18px", ...pos }}>
        <button type="button" aria-label={dismissLabel} style={{ position: "absolute", top: 8, right: 8, width: 22, height: 22, border: "none", background: "transparent", color: "#24143070", fontSize: 14, borderRadius: 6, cursor: "pointer" }}>×</button>
        <p style={{ margin: isBanner ? 0 : "0 0 10px", fontSize: 13.5, fontWeight: 700, paddingRight: isBanner ? 0 : 18, flex: isBanner ? 1 : "initial" }}>{question}</p>
        {!isBanner && (
          <textarea placeholder={placeholder} aria-label={placeholder} rows={2} style={{ width: "100%", boxSizing: "border-box", border: "1.5px solid #24143025", borderRadius: 8, padding: "8px 10px", fontSize: 12.5, resize: "none", marginBottom: 10 }} />
        )}
        <div style={{ display: "flex", justifyContent: isBanner ? "flex-start" : "flex-end", gap: 8 }}>
          <button type="button" style={{ background: "none", border: "1.5px solid #24143025", borderRadius: 7, padding: "6px 12px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>{dismissLabel}</button>
          {!isBanner && (
            <button type="button" style={{ background: accent, border: "1.5px solid " + accent, borderRadius: 7, padding: "6px 12px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Send</button>
          )}
        </div>
      </div>
    </div>
  );
}
